create schema if not exists placewise;
create extension if not exists postgis;
set search_path to placewise, public, extensions;
create table profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, created_at timestamptz not null default now());
create table saved_searches (id uuid primary key default gen_random_uuid(), user_id uuid not null references profiles(id) on delete cascade, name text not null, mode text not null check(mode in ('live','work','business')), criteria jsonb not null, created_at timestamptz not null default now());
create table location_cells (h3_index text primary key, resolution smallint not null, centre_lat double precision not null, centre_lng double precision not null, boundary geometry(Polygon,4326) not null, town text, postcode_sector text, local_authority text, region text, school_score smallint, primary_school_score smallint, secondary_school_score smallint, crime_score smallint, green_space_score smallint, rurality_score smallint, amenity_score smallint, restaurant_score smallint, rail_access_score smallint, motorway_access_score smallint, broadband_score smallint, healthcare_score smallint, flood_risk_score smallint, employment_density_score smallint, typical_house_price integer, typical_detached_price integer, typical_semi_price integer, typical_flat_price integer, data_quality_score smallint, last_updated timestamptz not null default now());
create index location_cells_boundary_gix on location_cells using gist(boundary);create index location_cells_region_idx on location_cells(region);create index location_cells_postcode_idx on location_cells(postcode_sector);create index location_cells_scores_idx on location_cells(school_score,green_space_score,crime_score);
create table travel_time_cache (id bigint generated always as identity primary key, origin_h3 text not null, destination_h3 text not null, transport_mode text not null, time_profile text not null default 'weekday', minutes smallint not null, source text not null, calculated_at timestamptz not null default now(), expires_at timestamptz not null, unique(origin_h3,destination_h3,transport_mode,time_profile));
create table optimisation_runs (id uuid primary key default gen_random_uuid(), user_id uuid references profiles(id) on delete set null, saved_search_id uuid references saved_searches(id) on delete set null, criteria jsonb not null, engine_version text not null, created_at timestamptz not null default now());
create table optimisation_results (id bigint generated always as identity primary key, run_id uuid not null references optimisation_runs(id) on delete cascade, h3_index text not null references location_cells(h3_index), rank integer not null, overall_score numeric(5,2) not null, commute_score numeric(5,2), lifestyle_score numeric(5,2), affordability_score numeric(5,2), is_pareto_efficient boolean not null default false, explanation_facts jsonb not null default '{}');create index optimisation_results_run_rank on optimisation_results(run_id,rank);
create table saved_locations (user_id uuid not null references profiles(id) on delete cascade, h3_index text not null references location_cells(h3_index), notes text, created_at timestamptz not null default now(), primary key(user_id,h3_index));
alter table profiles enable row level security;alter table saved_searches enable row level security;alter table saved_locations enable row level security;alter table optimisation_runs enable row level security;
create policy "Users manage own profile" on profiles for all using(auth.uid()=id);create policy "Users manage own searches" on saved_searches for all using(auth.uid()=user_id);create policy "Users manage own locations" on saved_locations for all using(auth.uid()=user_id);create policy "Users view own runs" on optimisation_runs for select using(auth.uid()=user_id);
